package api

const standardizationTemplates = `
{{define "padronizacao"}}{{template "topo" .}}
<div class="std-cab"><div><h1>Padronização de computadores</h1><p class="muted">Defina os aplicativos e atalhos que cada grupo precisa receber.</p></div><div class="grupo-btn"><a class="btn" href="/painel/padronizacao">Novo grupo</a><a class="btn" href="/painel/padronizacao?basico=1">Criar padrão básico</a></div></div>
<p class="aviso atencao">Aplicação automática no <strong>Windows</strong>. Aplicativos são instalados para o computador; atalhos são mantidos na sessão de cada usuário. Atualize servidor e agentes para esta versão antes de ativar os grupos.</p>
<div class="card"><div class="card-cab"><h2>Grupos e padrões</h2><span class="muted">{{len .Policies}} cadastrados</span></div>
{{if .Policies}}<div class="tabela"><table><thead><tr><th>Grupo</th><th>Aplicação</th><th>Destinos</th><th>Aplicativos</th><th>Atalhos</th><th>Ações</th></tr></thead><tbody>
{{range .Policies}}<tr><td><strong>{{.Name}}</strong>{{if .Description}}<small class="std-detalhe">{{.Description}}</small>{{end}}</td><td>{{if .Enabled}}<span class="estado em_dia">ativo</span>{{else}}<span class="estado desconhecido">rascunho / desativado</span>{{end}}</td><td>{{if .AllMachines}}Todos os computadores Windows{{else}}{{len .Machines}} computadores · {{len .ADGroups}} grupos AD{{end}}</td><td>{{len .Apps}}</td><td>{{len .Shortcuts}}</td><td><a class="btn" href="/painel/padronizacao?grupo={{.ID}}">Editar</a><details class="std-excluir"><summary>Excluir grupo</summary><p>A configuração será removida. Aplicativos instalados permanecem. Jobs já emitidos podem ser cancelados na tela Jobs, quando ainda pendentes.</p><form method="post" action="/painel/padronizacao/{{.ID}}/excluir"><input type="hidden" name="revisao" value="{{.Revision}}"><button class="perigo" type="submit">Excluir configuração</button></form></details></td></tr>{{end}}
</tbody></table></div>{{else}}<p class="muted">Crie um padrão básico e grupos como Financeiro e RH. Os padrões aplicáveis se somam, sem instalar o mesmo aplicativo duas vezes.</p>{{end}}</div>

<div class="card"><div class="card-cab"><h2>{{if .Editor.ID}}Editar · {{.Editor.Name}}{{else}}Novo grupo de padronização{{end}}</h2></div>
<form method="post" action="/painel/padronizacao" class="std-form">
<input type="hidden" name="id" value="{{.Editor.ID}}"><input type="hidden" name="revisao" value="{{.Editor.Revision}}">
<div class="std-duas"><label>Nome do grupo<input name="nome" value="{{.Editor.Name}}" maxlength="80" placeholder="Financeiro, RH ou Padrão básico" required></label><label>Descrição<input name="descricao" value="{{.Editor.Description}}" maxlength="500" placeholder="O que este grupo precisa receber"></label></div>
<label class="std-check"><input type="checkbox" name="ativo" value="1"{{if .Editor.Enabled}} checked{{end}}> Ativo — instalar e manter automaticamente o padrão</label>
<fieldset><legend>Quem recebe este padrão?</legend>
<label class="std-check"><input type="checkbox" name="todos" value="1"{{if .Editor.AllMachines}} checked{{end}}> Padrão básico para todos os computadores Windows</label>
<p class="muted">Para grupos específicos, deixe o padrão básico desmarcado e escolha computadores, grupos do AD ou ambos. Basta corresponder a um dos destinos.</p>
<div class="std-duas"><label>Computadores do grupo<select name="maquina" multiple size="7">{{range .Machines}}<option value="{{.ID}}"{{if .Selected}} selected{{end}}>{{.Name}} · {{.OS}} · {{.ID}}</option>{{end}}</select><small>Selecione vários com Ctrl ou Shift.</small></label>
<label>Grupos do AD dos usuários<textarea name="grupos_ad" rows="7" placeholder="CORP\Financeiro&#10;CORP\RH">{{.ADText}}</textarea><small>Um grupo por linha ou separado por vírgula. A associação vem do token do Windows e é atualizada no logon. Com domínio informado, ele deve corresponder.</small></label></div>
</fieldset>

<fieldset><legend>Aplicativos obrigatórios</legend><p class="muted">Instala o que falta e atualiza até a versão aprovada mais recente. Versões superiores são mantidas. Instaladores são conferidos e jobs são assinados pelo fluxo normal do patchd.</p>
{{if .CatalogOff}}<p class="aviso atencao">O catálogo de aplicativos não está configurado. Você pode configurar os atalhos enquanto prepara o catálogo.</p>{{end}}
<div class="std-apps">{{range .Apps}}<label class="std-app"><input type="checkbox" name="aplicativo" value="{{.ID}}"{{if .Selected}} checked{{end}}><span><strong>{{.Name}}</strong><small>{{if .Ready}}Há instalador aprovado; a compatibilidade será avaliada por computador.{{else}}Aguardando instalador aprovado em Patch › Terceiros.{{end}}</small></span></label>{{else}}<p class="muted">Nenhum aplicativo com instalação automatizada disponível no catálogo.</p>{{end}}</div>
</fieldset>

<fieldset><legend>Atalhos padrão na Área de Trabalho do usuário</legend><p class="muted">Configure sites, aplicativos .exe ou pastas. Os ícones usam os padrões do Windows ou o ícone do próprio aplicativo. Arquivos pessoais e atalhos modificados pelo usuário são preservados e relatados como conflito.</p>
{{range .ShortcutRows}}<div class="std-atalho"><label>Nome do atalho {{.Index}}<input name="atalho_nome" value="{{.Name}}" maxlength="64" placeholder="Portal Financeiro"></label><label>Tipo<select name="atalho_tipo"><option value="site"{{if eq .Kind "site"}} selected{{end}}>Site</option><option value="aplicativo"{{if eq .Kind "aplicativo"}} selected{{end}}>Aplicativo</option><option value="pasta"{{if eq .Kind "pasta"}} selected{{end}}>Pasta</option></select></label><label class="std-destino">Destino<input name="atalho_destino" value="{{.Target}}" maxlength="1024" placeholder="https://portal.exemplo ou C:\Program Files\Aplicativo\app.exe"></label><label>Ícone<select name="atalho_icone"><option value=""{{if eq .Icon ""}} selected{{end}}>Padrão do destino</option><option value="site"{{if eq .Icon "site"}} selected{{end}}>Site</option><option value="aplicativo"{{if eq .Icon "aplicativo"}} selected{{end}}>Aplicativo</option><option value="pasta"{{if eq .Icon "pasta"}} selected{{end}}>Pasta</option><option value="documento"{{if eq .Icon "documento"}} selected{{end}}>Documento</option></select></label></div>{{end}}
<small class="muted">Linhas vazias são ignoradas. Salve para disponibilizar mais linhas, até 24 atalhos por grupo. Em grupos sobrepostos, atalhos com o mesmo nome e destinos diferentes ficam bloqueados até resolver o conflito.</small>
</fieldset>
<div class="std-salvar"><button type="submit">Salvar grupo</button><span class="muted">Grupo ativo aplica automaticamente nas próximas avaliações do agente.</span></div>
</form></div>

<div class="card"><div class="card-cab"><h2>Acompanhamento da aplicação</h2><span class="muted">Até 500 avaliações recentes por computador e usuário</span></div>
<p class="muted">Aplicativos são confirmados pelo inventário posterior à instalação. Atalhos mostram o último relato da sessão do usuário, com sua data. Sem relato não significa conforme. Desativar ou excluir um grupo não desinstala programas nem desfaz jobs já emitidos.</p>
{{if .States}}<div class="tabela"><table><thead><tr><th>Computador / sessão</th><th>Grupos aplicáveis</th><th>Aplicativos</th><th>Relato dos atalhos</th><th>Quando</th></tr></thead><tbody>{{range .States}}<tr><td><a href="/painel/maquinas/{{.MachineID}}">{{.Name}}</a><small class="std-detalhe">{{.Account}}</small></td><td>{{if .Policies}}{{.Policies}}{{else}}Nenhum padrão aplicável{{end}}{{range .Warnings}}<small class="std-alerta">{{.}}</small>{{end}}</td><td>{{range .Apps}}<div class="std-app-status"><strong>{{.Name}}</strong> <span class="std-estado std-{{.State}}">{{.Label}}</span>{{if .Target}} <span class="muted">{{.Target}}</span>{{end}}{{if .JobID}} <a href="/painel/jobs">job {{.JobID}}</a>{{end}}<small class="std-detalhe">{{.Detail}}</small></div>{{else}}Sem aplicativos neste padrão{{end}}</td><td>{{.Shortcuts}}{{if .Reported}}<small class="std-detalhe">Relatado em {{.Reported}}</small>{{end}}</td><td>{{.When}}</td></tr>{{end}}</tbody></table></div>
{{else}}<p class="muted">Nenhuma avaliação recebida. Publique um agente com suporte à padronização. Padrões por computador são avaliados no check-in; grupos do AD e atalhos, pela Central na sessão do usuário.</p>{{end}}</div>
{{template "fim"}}{{end}}
`

const standardizationCSS = `
.std-cab{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem;margin-bottom:1.25rem}.std-cab h1{margin-bottom:.4rem}.std-cab p{margin:0}.std-detalhe{display:block;font-size:.78rem;color:var(--muted);line-height:1.5;margin-top:.3rem}
.std-duas{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.std-form label{display:flex;flex-direction:column;gap:.4rem;font-size:.88rem}.std-form input:not([type=checkbox]),.std-form textarea,.std-form select{width:100%;min-width:0}.std-form label.std-check{display:flex;flex-direction:row;align-items:center;gap:.5rem;margin:1rem 0;font-weight:600}.std-form fieldset{border:1px solid var(--borda);border-radius:var(--raio);padding:1rem;margin:1.25rem 0}.std-form legend{font-weight:600;padding:0 .4rem}.std-form small{font-size:.76rem;color:var(--muted);line-height:1.5}
.std-apps{display:grid;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr));gap:.75rem}.std-form label.std-app{flex-direction:row;gap:.6rem;align-items:flex-start;border:1px solid var(--borda);border-radius:6px;padding:.8rem}.std-app input{margin-top:.2rem}.std-app small{display:block;margin-top:.35rem}
.std-atalho{display:grid;grid-template-columns:1.2fr .75fr 2fr 1fr;gap:.75rem;padding:.8rem 0;border-bottom:1px solid var(--borda)}.std-atalho:last-of-type{border:0}.std-salvar{display:flex;gap:1rem;align-items:center;flex-wrap:wrap}.std-excluir{display:inline-block;margin-left:.5rem}.std-excluir summary{cursor:pointer;color:var(--vermelho);font-size:.8rem}.std-excluir p{max-width:22rem;font-size:.8rem}.std-app-status+.std-app-status{margin-top:.75rem}.std-estado{font-size:.72rem;font-weight:600;border-radius:999px;padding:.15rem .45rem;white-space:nowrap;background:#edf2fb;color:#3b4a6b}.std-em_dia{background:#e7f6ec;color:#16692f}.std-falhou,.std-bloqueado{background:#fbe9e9;color:#a12424}.std-aguardando{background:#fff4dc;color:#8a5a00}.std-alerta{display:block;color:var(--vermelho);font-size:.78rem;margin-top:.4rem}
@media(max-width:1000px){.std-atalho{grid-template-columns:1fr 1fr}.std-cab{flex-direction:column}}@media(max-width:650px){.std-duas,.std-atalho{grid-template-columns:1fr}.std-apps{grid-template-columns:1fr}}
`
